-- Initial PostgreSQL ledger schema. This file is an explicit migration artifact:
-- it is never imported or applied by application startup.
-- IDs are generated by the application; timestamps are stored as timestamptz.
-- Keep historical rows restrictive: deleting a parent must not erase evidence.
CREATE TABLE workspaces (
    workspace_id UUID PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE instruments (
    instrument_id UUID PRIMARY KEY,
    canonical_symbol TEXT NOT NULL UNIQUE,
    asset_class TEXT NOT NULL CHECK (asset_class IN ('equity', 'crypto', 'future', 'other')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (instrument_id, canonical_symbol)
);

CREATE TABLE trading_accounts (
    account_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    venue TEXT NOT NULL,
    profile TEXT NOT NULL CHECK (profile IN ('demo', 'paper', 'production')),
    label TEXT NOT NULL,
    enabled BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (workspace_id, venue, profile, label),
    UNIQUE (workspace_id, account_id)
);

CREATE TABLE analysis_jobs (
    job_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    mode TEXT NOT NULL CHECK (mode IN ('mock', 'live', 'backtest')),
    status TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at TIMESTAMPTZ,
    UNIQUE (workspace_id, job_id)
);
CREATE INDEX idx_analysis_jobs_workspace_created
    ON analysis_jobs(workspace_id, created_at DESC);
CREATE INDEX idx_analysis_jobs_workspace_status_created
    ON analysis_jobs(workspace_id, status, created_at DESC);

CREATE TABLE analysis_runs (
    run_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    job_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    attempt INTEGER NOT NULL DEFAULT 1 CHECK (attempt > 0),
    trade_date DATE NOT NULL,
    run_type TEXT NOT NULL CHECK (run_type IN ('analysis', 'backtest', 'replay', 'other')),
    mode TEXT NOT NULL CHECK (mode IN ('mock', 'live', 'backtest')),
    status TEXT NOT NULL,
    config_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
    input_provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    FOREIGN KEY (workspace_id, job_id)
        REFERENCES analysis_jobs(workspace_id, job_id),
    UNIQUE (workspace_id, run_id),
    UNIQUE (workspace_id, run_id, instrument_id),
    UNIQUE (workspace_id, job_id, instrument_id, attempt),
    UNIQUE (workspace_id, job_id, instrument_id, attempt, run_id)
);
CREATE INDEX idx_analysis_runs_workspace_created
    ON analysis_runs(workspace_id, created_at DESC);
CREATE INDEX idx_analysis_runs_instrument_trade_date
    ON analysis_runs(instrument_id, trade_date DESC, created_at DESC);

CREATE TABLE job_results (
    job_result_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    job_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    attempt INTEGER NOT NULL DEFAULT 1 CHECK (attempt > 0),
    run_id UUID,
    status TEXT NOT NULL,
    result JSONB NOT NULL DEFAULT '{}'::jsonb,
    completed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (workspace_id, job_id)
        REFERENCES analysis_jobs(workspace_id, job_id),
    FOREIGN KEY (workspace_id, job_id, instrument_id, attempt, run_id)
        REFERENCES analysis_runs(workspace_id, job_id, instrument_id, attempt, run_id),
    UNIQUE (workspace_id, job_result_id),
    UNIQUE (workspace_id, job_result_id, run_id),
    UNIQUE (workspace_id, job_id, instrument_id, attempt)
);
CREATE INDEX idx_job_results_job_status
    ON job_results(workspace_id, job_id, status, instrument_id);

CREATE TABLE run_events (
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    run_id UUID NOT NULL,
    seq BIGINT NOT NULL CHECK (seq >= 0),
    event_id UUID NOT NULL UNIQUE,
    event_type TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, run_id, seq),
    FOREIGN KEY (workspace_id, run_id)
        REFERENCES analysis_runs(workspace_id, run_id)
);

CREATE TABLE trading_decisions (
    decision_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    run_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    decision_text TEXT NOT NULL,
    structured_output JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (workspace_id, run_id, instrument_id)
        REFERENCES analysis_runs(workspace_id, run_id, instrument_id),
    UNIQUE (workspace_id, decision_id),
    UNIQUE (workspace_id, run_id, decision_id, instrument_id)
);

CREATE TABLE decision_context_links (
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    decision_id UUID NOT NULL,
    referenced_decision_id UUID NOT NULL,
    context_kind TEXT NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    included_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, decision_id, referenced_decision_id, context_kind),
    UNIQUE (workspace_id, decision_id, context_kind, position),
    FOREIGN KEY (workspace_id, decision_id)
        REFERENCES trading_decisions(workspace_id, decision_id),
    FOREIGN KEY (workspace_id, referenced_decision_id)
        REFERENCES trading_decisions(workspace_id, decision_id),
    CHECK (decision_id <> referenced_decision_id)
);

CREATE TABLE approval_requests (
    approval_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    job_result_id UUID,
    run_id UUID,
    decision_id UUID,
    account_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    idempotency_key TEXT NOT NULL,
    status TEXT NOT NULL CHECK (
        status IN ('pending', 'claimed', 'rejected', 'expired', 'executing',
                   'executed', 'execute_failed', 'submission_unknown')
    ),
    plan_snapshot JSONB NOT NULL,
    side TEXT NOT NULL CHECK (side IN ('buy', 'sell')),
    quantity NUMERIC NOT NULL CHECK (quantity > 0),
    expires_at TIMESTAMPTZ NOT NULL,
    claimed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at TIMESTAMPTZ,
    FOREIGN KEY (workspace_id, job_result_id, run_id)
        REFERENCES job_results(workspace_id, job_result_id, run_id) MATCH FULL,
    FOREIGN KEY (workspace_id, run_id, instrument_id)
        REFERENCES analysis_runs(workspace_id, run_id, instrument_id),
    FOREIGN KEY (workspace_id, run_id, decision_id, instrument_id)
        REFERENCES trading_decisions(workspace_id, run_id, decision_id, instrument_id) MATCH FULL,
    FOREIGN KEY (workspace_id, account_id)
        REFERENCES trading_accounts(workspace_id, account_id),
    UNIQUE (workspace_id, approval_id),
    UNIQUE (workspace_id, approval_id, account_id, instrument_id),
    UNIQUE (workspace_id, idempotency_key),
    CHECK (job_result_id IS NULL OR run_id IS NOT NULL),
    CHECK (decision_id IS NULL OR run_id IS NOT NULL)
);
CREATE INDEX idx_approval_requests_workspace_status_expiry
    ON approval_requests(workspace_id, status, expires_at);

CREATE TABLE approval_events (
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    approval_id UUID NOT NULL,
    seq BIGINT NOT NULL CHECK (seq >= 0),
    approval_event_id UUID NOT NULL UNIQUE,
    event_type TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, approval_id, seq),
    FOREIGN KEY (workspace_id, approval_id)
        REFERENCES approval_requests(workspace_id, approval_id)
);

CREATE TABLE execution_orders (
    order_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    account_id UUID NOT NULL,
    approval_id UUID,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    client_order_key TEXT NOT NULL CHECK (client_order_key ~ '^[0-9a-f]{64}$'),
    client_order_id TEXT NOT NULL CHECK (
        client_order_id = 'ta_' || substr(client_order_key, 1, 32)
    ),
    venue_order_id TEXT,
    market_type TEXT NOT NULL CHECK (market_type IN ('spot', 'perpetual', 'future')),
    side TEXT NOT NULL CHECK (side IN ('buy', 'sell')),
    order_type TEXT NOT NULL,
    quantity NUMERIC NOT NULL CHECK (quantity > 0),
    limit_price NUMERIC,
    reduce_only BOOLEAN NOT NULL DEFAULT false,
    status TEXT NOT NULL CHECK (
        status IN ('created', 'submitting', 'submission_unknown', 'open',
                   'partially_filled', 'filled', 'cancel_pending', 'cancelled',
                   'rejected', 'failed')
    ),
    submitted_at TIMESTAMPTZ,
    acknowledged_at TIMESTAMPTZ,
    closed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    FOREIGN KEY (workspace_id, account_id)
        REFERENCES trading_accounts(workspace_id, account_id),
    FOREIGN KEY (workspace_id, approval_id, account_id, instrument_id)
        REFERENCES approval_requests(workspace_id, approval_id, account_id, instrument_id),
    UNIQUE (workspace_id, order_id),
    UNIQUE (workspace_id, account_id, order_id),
    UNIQUE (workspace_id, account_id, order_id, instrument_id),
    UNIQUE (account_id, client_order_key)
);
CREATE UNIQUE INDEX uq_execution_orders_active_client_id
    ON execution_orders(account_id, client_order_id)
    WHERE status IN ('created', 'submitting', 'submission_unknown', 'open',
                     'partially_filled', 'cancel_pending');
CREATE UNIQUE INDEX uq_execution_orders_venue_id
    ON execution_orders(account_id, venue_order_id)
    WHERE venue_order_id IS NOT NULL;
CREATE UNIQUE INDEX uq_execution_orders_approval
    ON execution_orders(workspace_id, approval_id)
    WHERE approval_id IS NOT NULL;

CREATE TABLE execution_events (
    execution_event_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    account_id UUID NOT NULL,
    order_id UUID,
    venue_event_id TEXT,
    idempotency_key TEXT NOT NULL,
    event_type TEXT NOT NULL,
    source TEXT NOT NULL CHECK (
        source IN ('application', 'venue', 'reconciliation', 'risk')
    ),
    occurred_at TIMESTAMPTZ NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    payload JSONB NOT NULL DEFAULT '{}'::jsonb,
    FOREIGN KEY (workspace_id, account_id)
        REFERENCES trading_accounts(workspace_id, account_id),
    FOREIGN KEY (workspace_id, account_id, order_id)
        REFERENCES execution_orders(workspace_id, account_id, order_id),
    UNIQUE (account_id, idempotency_key)
);
CREATE UNIQUE INDEX uq_execution_events_venue_id
    ON execution_events(account_id, venue_event_id)
    WHERE venue_event_id IS NOT NULL;

CREATE TABLE order_fills (
    fill_id UUID PRIMARY KEY,
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    account_id UUID NOT NULL,
    order_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    venue_trade_id TEXT NOT NULL,
    side TEXT NOT NULL CHECK (side IN ('buy', 'sell')),
    quantity NUMERIC NOT NULL CHECK (quantity > 0),
    price NUMERIC NOT NULL CHECK (price > 0),
    fee NUMERIC,
    fee_currency TEXT,
    occurred_at TIMESTAMPTZ NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    raw_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    FOREIGN KEY (workspace_id, account_id, order_id, instrument_id)
        REFERENCES execution_orders(workspace_id, account_id, order_id, instrument_id),
    UNIQUE (account_id, venue_trade_id)
);
CREATE INDEX idx_order_fills_account_time
    ON order_fills(account_id, occurred_at DESC);

CREATE TABLE position_snapshots (
    workspace_id UUID NOT NULL REFERENCES workspaces(workspace_id),
    account_id UUID NOT NULL,
    instrument_id UUID NOT NULL REFERENCES instruments(instrument_id),
    market_type TEXT NOT NULL CHECK (market_type IN ('spot', 'perpetual', 'future')),
    position_side TEXT NOT NULL CHECK (position_side IN ('net', 'long', 'short')),
    quantity NUMERIC NOT NULL,
    entry_price NUMERIC,
    mark_price NUMERIC,
    unrealized_pnl NUMERIC,
    currency TEXT,
    venue_updated_at TIMESTAMPTZ,
    revision BIGINT NOT NULL DEFAULT 0,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, account_id, instrument_id, market_type, position_side),
    FOREIGN KEY (workspace_id, account_id)
        REFERENCES trading_accounts(workspace_id, account_id)
);

-- UPDATE ... RETURNING is a single-row compare-and-set. Concurrent workers
-- cannot both claim a pending, unexpired approval. The order row and claim
-- should be committed in the same caller-owned transaction before venue I/O.
CREATE FUNCTION claim_approval(p_workspace_id UUID, p_approval_id UUID)
RETURNS SETOF approval_requests
LANGUAGE sql
AS $$
    UPDATE approval_requests
       SET status = 'claimed', claimed_at = clock_timestamp()
     WHERE workspace_id = p_workspace_id
       AND approval_id = p_approval_id
       AND status = 'pending'
       AND expires_at > clock_timestamp()
    RETURNING *;
$$;

